   {type:"sort", title:"What Do the Tablets Show?", prompt:"Sort each statement. Is it something the tablets suggest, or something they leave out?",
    bins:["Tablets suggest","Tablets leave out"],
    items:[{t:"Workers received rations of grain and other foods.",bin:0},{t:"Women and children appear as workers.",bin:0},{t:"Skilled workers often got larger rations than helpers.",bin:0},{t:"Records were kept by trained scribes.",bin:0},{t:"How workers felt about their jobs.",bin:1},{t:"The songs people sang at work.",bin:1},{t:"What happened in battles.",bin:1},{t:"What the king ate for dinner every night.",bin:1}]},
   {type:"order", title:"From Wet Clay to Museum", prompt:"Put these steps in order, from the scribe’s desk to today’s museum.",
    items:["A scribe presses cuneiform into wet clay with a reed","The tablet dries or is baked and is stored in the fortification wall","Archaeologists dig up the tablets at Persepolis (1933)","Scholars read the Elamite writing and translate it","Historians use the tablets as evidence about daily life"]},
   {type:"reveal", title:"Fact or Careful Guess?", prompt:"Tap each card to see whether it is evidence or an inference.",
    cards:[{front:"Workers were paid in barley, flour and other foods.",back:"Evidence. The tablets record these rations directly."},{front:"A worker with a bigger ration was probably doing harder or more skilled work.",back:"A careful inference. The pattern suggests it, but the tablets rarely explain why."},{front:"Everyone in the empire spoke Aramaic at home.",back:"Not supported. Aramaic was widely used for official business and trade, but many languages were spoken."},{front:"Persian boys were taught to ride, shoot and tell the truth.",back:"Reported by Herodotus, a Greek writer. It is one source, so we say ‘according to Herodotus’."}]}
